// EXEMPLO: substitua a lista abaixo pela sua fonte (planilha, API, etc.).
// Defina o ID da campanha (UUID) do LeadForge e monte 1 item de saida com o corpo do POST (ate 100 leads por chamada).
const campaignId = '00000000-0000-4000-8000-000000000000'; // TROCAR pelo UUID da campanha
const fonte = [
  { nome: 'Maria Exemplo', empresa: 'Empresa Exemplo', email: 'maria@exemplo.com', telefone: '(11) 91234-5678' },
];
const leads = fonte.map((r) => ({
  name: r.nome,
  company: r.empresa,
  email: r.email,
  phone: r.telefone,
  source: 'n8n',
  externalId: r.id ? String(r.id) : undefined,
}));
return [{ json: { campaignId, leads: leads.slice(0, 100) } }];
